import json
import re
import shutil
import subprocess
import tempfile
import unittest
from pathlib import Path

TARGET = Path(__file__).resolve().parent / "markdown-notebook.html"
SCRIPT_ID = "app"
FEATURES = ["notes", "markdown", "tags", "links", "backlinks", "search", "outline", "stats",
            "pins", "history", "exporter", "persist"]

DRIVER = r"""
const fs = require('fs');
const vm = require('vm');
const noop = () => {};
function el() {
  return {
    innerHTML: '', textContent: '', value: '', checked: false, style: {}, dataset: {},
    children: [], childNodes: [], parentNode: null,
    classList: { add: noop, remove: noop, toggle: noop, contains: () => false },
    addEventListener: noop, removeEventListener: noop, dispatchEvent: noop,
    appendChild: (x) => x, append: noop, prepend: noop, removeChild: noop,
    replaceChildren: noop, insertBefore: noop, remove: noop, setAttribute: noop,
    removeAttribute: noop, getAttribute: () => null, hasAttribute: () => false,
    focus: noop, blur: noop, click: noop, closest: () => null, matches: () => false,
    querySelector: () => el(), querySelectorAll: () => [], getElementsByTagName: () => [],
    getBoundingClientRect: () => ({ x: 0, y: 0, width: 0, height: 0, top: 0, left: 0, right: 0, bottom: 0 }),
  };
}
const bag = new Map();
const storage = {
  getItem: (k) => (bag.has(String(k)) ? bag.get(String(k)) : null),
  setItem: (k, v) => { bag.set(String(k), String(v)); },
  removeItem: (k) => { bag.delete(String(k)); },
  clear: () => bag.clear(),
  key: (i) => Array.from(bag.keys())[i] ?? null,
  get length() { return bag.size; },
};
Object.defineProperty(globalThis, 'localStorage', { value: storage, configurable: true, writable: true });
globalThis.document = Object.assign(el(), {
  getElementById: () => el(), createElement: () => el(), createElementNS: () => el(),
  createTextNode: (t) => ({ textContent: String(t) }), createDocumentFragment: () => el(),
  body: el(), head: el(), documentElement: el(), readyState: 'loading',
});
globalThis.window = globalThis;
globalThis.location = { hash: '', href: '', search: '' };
globalThis.history = { pushState: noop, replaceState: noop };
globalThis.requestAnimationFrame = () => 0;
globalThis.alert = noop; globalThis.confirm = () => true; globalThis.prompt = () => null;

const out = { app: false, features: {} };
try {
  vm.runInThisContext(fs.readFileSync('app.js', 'utf8'), { filename: 'app.js' });
} catch (e) {
  out.load_error = String((e && e.stack) || e).slice(0, 800);
}
const App = globalThis.App;
out.app = !!(App && App.features && typeof App.features === 'object');

const NOTES = [
  { id: 'n1', title: 'Project Plan', body: '# Project Plan\n\nKick-off with **the team** and review [[Budget Notes]].\n\n## Milestones\n\n- Draft #planning\n- Ship #planning #release', created: 1000, updated: 5000, pinned: false },
  { id: 'n2', title: 'Budget Notes', body: 'Numbers for the plan, see [[Project Plan]] and [[Missing Page]]. #finance', created: 2000, updated: 9000, pinned: false },
  { id: 'n3', title: 'Reading List', body: 'Books about *focus* and `deep work`. #reading #planning', created: 3000, updated: 7000, pinned: true },
  { id: 'n4', title: 'Grocery', body: 'Milk, eggs, bread. Budget for the week is small. See [[reading list]].', created: 4000, updated: 6000, pinned: false },
];
const ids = (list) => (list || []).map((n) => String(n.id));
const frozen = JSON.stringify(NOTES);

function feature(name, fn) {
  const r = { present: false, has_model: false, has_render: false };
  try {
    const f = App && App.features && App.features[name];
    r.present = !!f;
    if (f) {
      r.has_model = !!f.model && typeof f.model === 'object';
      r.has_render = typeof f.render === 'function';
      Object.assign(r, fn(f.model));
      r.mutated_input = JSON.stringify(NOTES) !== frozen;
    }
  } catch (e) {
    r.error = String((e && e.stack) || e).slice(0, 600);
  }
  out.features[name] = r;
}

feature('notes', (m) => {
  const one = m.create(NOTES, 'New Note', 'body text', 12345);
  const two = m.create(one, 'Second', '', 12346);
  const fresh = one[one.length - 1];
  const patched = m.update(NOTES, 'n4', { title: 'Groceries' }, 20000);
  const n4 = patched.find((n) => n.id === 'n4');
  return {
    original: NOTES.length, after_one: one.length, after_two: two.length,
    ids_two: ids(two),
    fresh: { title: fresh.title, body: fresh.body, created: fresh.created, updated: fresh.updated, pinned: !!fresh.pinned, has_id: fresh.id !== undefined && fresh.id !== null && fresh.id !== '' },
    patched_len: patched.length,
    n4: { title: n4.title, body: n4.body, created: n4.created, updated: n4.updated },
    others_untouched: patched.filter((n) => n.id !== 'n4').map((n) => n.updated),
    removed: ids(m.remove(NOTES, 'n2')),
  };
});

feature('markdown', (m) => ({
  html: m.render('# Title\nSome **bold** and *it* with `code` here.\n\n## Sub\n\n- one\n- two\n\n[link](https://example.com/a)\n\n<script>alert(1)</script>'),
}));

feature('tags', (m) => ({
  list: m.tags('Draft #planning and #Release, then #planning again. # Not a tag\n#finance-2026 #a_b'),
  index: m.index(NOTES),
}));

feature('links', (m) => ({
  targets: m.links('see [[Project Plan]] and [[Missing Page]] and [[Project Plan]]'),
  hit: m.resolve(NOTES, 'budget notes'),
  miss: m.resolve(NOTES, 'Missing Page'),
}));

feature('backlinks', (m) => ({
  n1: ids(m.backlinks(NOTES, 'n1').map((x) => (typeof x === 'object' ? x : { id: x }))),
  n2: ids(m.backlinks(NOTES, 'n2').map((x) => (typeof x === 'object' ? x : { id: x }))),
  n3: ids(m.backlinks(NOTES, 'n3').map((x) => (typeof x === 'object' ? x : { id: x }))),
  n4: ids(m.backlinks(NOTES, 'n4').map((x) => (typeof x === 'object' ? x : { id: x }))),
}));

const asIds = (r) => (r || []).map((x) => String(typeof x === 'object' && x !== null ? x.id : x));
feature('search', (m) => ({
  budget: asIds(m.search(NOTES, 'budget')),
  plan: asIds(m.search(NOTES, 'plan')),
  two_terms: asIds(m.search(NOTES, 'week budget')),
  empty: asIds(m.search(NOTES, '')),
  blank: asIds(m.search(NOTES, '   ')),
  miss: asIds(m.search(NOTES, 'zzz')),
}));

feature('outline', (m) => ({
  items: m.outline('# Title\ntext\n## Part One\n### Deep\n#tag not heading\n## Part Two'),
}));

feature('stats', (m) => ({
  five: m.stats('One two three.\n\nFour five'),
  none: m.stats(''),
  long: m.stats(Array(401).fill('word').join(' ')),
}));

feature('pins', (m) => ({
  order: ids(m.order(NOTES)),
  on: m.toggle(NOTES, 'n1').map((n) => ({ id: n.id, pinned: !!n.pinned })),
  off: m.toggle(NOTES, 'n3').map((n) => ({ id: n.id, pinned: !!n.pinned })),
}));

feature('history', (m) => {
  const trail = [];
  let h = m.init('s0');
  const snap = (label) => trail.push({ label, present: m.present(h), undo: !!m.canUndo(h), redo: !!m.canRedo(h) });
  snap('init');
  h = m.push(h, 's1'); snap('push1');
  h = m.push(h, 's2'); snap('push2');
  h = m.undo(h); snap('undo1');
  h = m.undo(h); snap('undo2');
  h = m.undo(h); snap('undo3');
  h = m.redo(h); snap('redo1');
  h = m.push(h, 's3'); snap('push3');
  h = m.redo(h); snap('redo2');
  return { trail };
});

feature('exporter', (m) => {
  const text = m.toJson(NOTES);
  return {
    text,
    back: (m.fromJson(text) || []).map((n) => ({ id: String(n.id), title: n.title, body: n.body })),
    garbage: m.fromJson('not json at all'),
    wrong_shape: m.fromJson('{"x": 1}'),
  };
});

feature('persist', (m) => {
  const before = m.load();
  m.save({ notes: NOTES, ui: { current: 'n1' } });
  return { before, after: m.load(), stored: storage.length, raw_is_json: (() => {
    try { JSON.parse(storage.getItem(storage.key(0))); return true; } catch (e) { return false; }
  })() };
});

console.log(JSON.stringify(out));
"""


def node():
    return shutil.which("node") or shutil.which("node.exe")


def run_app(script):
    with tempfile.TemporaryDirectory() as tmp:
        d = Path(tmp)
        (d / "app.js").write_text(script, encoding="utf-8")
        (d / "driver.js").write_text(DRIVER, encoding="utf-8")
        done = subprocess.run([node(), str(d / "driver.js")], capture_output=True, text=True,
                              timeout=60, cwd=d)
        if done.returncode != 0:
            raise AssertionError("app script failed in node: %s" % done.stderr[-800:])
        return json.loads(done.stdout.strip().splitlines()[-1])


class Acceptance(unittest.TestCase):
    @classmethod
    def setUpClass(cls):
        cls.raw = TARGET.read_text(encoding="utf-8")
        m = re.search(r'<script[^>]*id=["\']%s["\'][^>]*>(.*?)</script>' % SCRIPT_ID, cls.raw, re.S | re.I)
        cls.script = m.group(1) if m else None
        cls.data, cls.error = None, None
        if cls.script and node():
            try:
                cls.data = run_app(cls.script)
            except (AssertionError, ValueError) as exc:
                cls.error = str(exc)

    def feature(self, name):
        """The measured model of one feature, plus its panel in the page."""
        self.assertIsNotNone(self.script, 'no <script id="%s"> block in the page' % SCRIPT_ID)
        if node() is None:
            raise unittest.SkipTest("node is required to run the app script")
        self.assertIsNone(self.error, self.error)
        self.assertIsNone(self.data.get("load_error"), "app script threw while loading: %s" % self.data.get("load_error"))
        self.assertTrue(self.data.get("app"), "the app script must define window.App.features")
        self.assertRegex(self.raw, r'id=["\']panel-%s["\']' % name, "no <section id=\"panel-%s\"> in the page" % name)
        got = self.data["features"].get(name)
        self.assertTrue(got and got.get("present"), "App.features.%s is missing" % name)
        self.assertTrue(got.get("has_model"), "App.features.%s.model must be an object of pure functions" % name)
        self.assertTrue(got.get("has_render"), "App.features.%s.render must be a function" % name)
        self.assertIsNone(got.get("error"), "App.features.%s.model threw: %s" % (name, got.get("error")))
        self.assertFalse(got.get("mutated_input"), "App.features.%s.model mutated its input list" % name)
        return got

    # --- the page ---------------------------------------------------------
    def test_page_is_one_self_contained_html_file(self):
        self.assertRegex(self.raw[:400].lower(), r"<!doctype html")
        for pat, why in ((r'src\s*=\s*["\'](https?:)?//', "external src"),
                         (r'href\s*=\s*["\'](https?:)?//', "external href"),
                         (r"@import", "css @import"),
                         (r'url\(\s*["\']?(https?:)?//', "external url()"),
                         (r"\bfetch\s*\(", "network fetch"),
                         (r"XMLHttpRequest", "XHR")):
            self.assertIsNone(re.search(pat, self.raw, re.I), "page must be self-contained: found %s" % why)
        self.assertIsNotNone(self.script, 'no <script id="%s"> block' % SCRIPT_ID)
        tag = re.search(r'<script[^>]*id=["\']%s["\'][^>]*>' % SCRIPT_ID, self.raw, re.I).group(0)
        self.assertNotIn("module", tag.lower(), "the app script must be a plain script, not type=module")
        self.assertRegex(self.raw, r"<nav\b", "the page needs a <nav> with the feature tabs")
        for name in FEATURES:
            self.assertRegex(self.raw, r'data-tab=["\']%s["\']' % name, "no tab for %s" % name)
            self.assertRegex(self.raw, r'id=["\']panel-%s["\']' % name, "no panel for %s" % name)

    def test_app_script_defines_every_feature(self):
        self.assertIsNotNone(self.script, 'no <script id="%s"> block' % SCRIPT_ID)
        if node() is None:
            raise unittest.SkipTest("node is required to run the app script")
        self.assertIsNone(self.error, self.error)
        self.assertIsNone(self.data.get("load_error"), "app script threw while loading: %s" % self.data.get("load_error"))
        self.assertTrue(self.data.get("app"), "the app script must define window.App.features")
        missing = [n for n in FEATURES if not (self.data["features"].get(n) or {}).get("present")]
        self.assertEqual(missing, [], "features missing from App.features: %s" % missing)

    # --- the twelve features, one test each --------------------------------
    def test_feature_notes(self):
        got = self.feature("notes")
        self.assertEqual(got["original"], 4, "create() must not change the list it was given")
        self.assertEqual(got["after_one"], 5)
        self.assertEqual(got["after_two"], 6)
        self.assertEqual(len(set(got["ids_two"])), 6, "every note needs a unique id")
        fresh = got["fresh"]
        self.assertTrue(fresh["has_id"])
        self.assertEqual(fresh["title"], "New Note")
        self.assertEqual(fresh["body"], "body text")
        self.assertEqual(fresh["created"], 12345)
        self.assertEqual(fresh["updated"], 12345)
        self.assertFalse(fresh["pinned"], "a new note starts unpinned")
        self.assertEqual(got["patched_len"], 4)
        self.assertEqual(got["n4"], {"title": "Groceries", "body": "Milk, eggs, bread. Budget for the week is small. See [[reading list]].",
                                     "created": 4000, "updated": 20000})
        self.assertEqual(got["others_untouched"], [5000, 9000, 7000], "update() touches only the named note")
        self.assertEqual(got["removed"], ["n1", "n3", "n4"])

    def test_feature_markdown(self):
        html = self.feature("markdown")["html"]
        self.assertIsInstance(html, str)
        self.assertRegex(html, r"<h1[^>]*>\s*Title\s*</h1>")
        self.assertRegex(html, r"<h2[^>]*>\s*Sub\s*</h2>")
        self.assertRegex(html, r"<strong>\s*bold\s*</strong>")
        self.assertRegex(html, r"<em>\s*it\s*</em>")
        self.assertRegex(html, r"<code>\s*code\s*</code>")
        self.assertRegex(html, r"<ul[^>]*>")
        self.assertRegex(html, r"<li[^>]*>\s*one\s*</li>")
        self.assertRegex(html, r"<li[^>]*>\s*two\s*</li>")
        self.assertRegex(html, r'<a\b[^>]*href="https://example\.com/a"[^>]*>\s*link\s*</a>')
        self.assertRegex(html, r"<p[^>]*>")
        self.assertNotIn("<script", html, "raw HTML in a note must be escaped, not rendered")
        self.assertIn("&lt;script&gt;", html)

    def test_feature_tags(self):
        got = self.feature("tags")
        self.assertEqual(got["list"], ["planning", "release", "finance-2026", "a_b"],
                         "lower-cased, distinct, first-appearance order, headings are not tags")
        self.assertEqual(got["index"], {"planning": ["n1", "n3"], "release": ["n1"], "finance": ["n2"], "reading": ["n3"]})

    def test_feature_links(self):
        got = self.feature("links")
        self.assertEqual(got["targets"], ["Project Plan", "Missing Page"])
        self.assertEqual(got["hit"], "n2", "titles resolve case-insensitively")
        self.assertIsNone(got["miss"], "an unknown title resolves to null")

    def test_feature_backlinks(self):
        got = self.feature("backlinks")
        self.assertEqual(got["n1"], ["n2"])
        self.assertEqual(got["n2"], ["n1"])
        self.assertEqual(got["n3"], ["n4"], "a [[reading list]] link reaches Reading List whatever its case")
        self.assertEqual(got["n4"], [])

    def test_feature_search(self):
        got = self.feature("search")
        self.assertEqual(got["budget"], ["n2", "n1", "n4"], "title matches rank before body matches, then list order")
        self.assertEqual(got["plan"], ["n1", "n2", "n3"])
        self.assertEqual(got["two_terms"], ["n4"], "every term must match somewhere in the note")
        self.assertEqual(got["empty"], ["n1", "n2", "n3", "n4"])
        self.assertEqual(got["blank"], ["n1", "n2", "n3", "n4"])
        self.assertEqual(got["miss"], [])

    def test_feature_outline(self):
        items = self.feature("outline")["items"]
        self.assertEqual([(i["level"], i["text"]) for i in items],
                         [(1, "Title"), (2, "Part One"), (3, "Deep"), (2, "Part Two")])

    def test_feature_stats(self):
        got = self.feature("stats")
        self.assertEqual(got["five"], {"words": 5, "chars": 25, "minutes": 1})
        self.assertEqual(got["none"], {"words": 0, "chars": 0, "minutes": 0})
        self.assertEqual(got["long"], {"words": 401, "chars": 401 * 5 - 1, "minutes": 3})

    def test_feature_pins(self):
        got = self.feature("pins")
        self.assertEqual(got["order"], ["n3", "n2", "n4", "n1"], "pinned first, then most recently updated")
        self.assertEqual(got["on"], [{"id": "n1", "pinned": True}, {"id": "n2", "pinned": False},
                                     {"id": "n3", "pinned": True}, {"id": "n4", "pinned": False}])
        self.assertEqual(got["off"], [{"id": "n1", "pinned": False}, {"id": "n2", "pinned": False},
                                      {"id": "n3", "pinned": False}, {"id": "n4", "pinned": False}])

    def test_feature_history(self):
        trail = {t["label"]: t for t in self.feature("history")["trail"]}
        want = {
            "init": ("s0", False, False),
            "push1": ("s1", True, False),
            "push2": ("s2", True, False),
            "undo1": ("s1", True, True),
            "undo2": ("s0", False, True),
            "undo3": ("s0", False, True),
            "redo1": ("s1", True, True),
            "push3": ("s3", True, False),
            "redo2": ("s3", True, False),
        }
        for label, (present, undo, redo) in want.items():
            self.assertEqual((trail[label]["present"], trail[label]["undo"], trail[label]["redo"]),
                             (present, undo, redo), "after %s" % label)

    def test_feature_exporter(self):
        got = self.feature("exporter")
        parsed = json.loads(got["text"])
        self.assertIsInstance(parsed, dict, "the export is a JSON object holding the notes")
        self.assertEqual(len(parsed.get("notes") or []), 4)
        self.assertEqual([n["id"] for n in got["back"]], ["n1", "n2", "n3", "n4"])
        self.assertEqual([n["title"] for n in got["back"]], ["Project Plan", "Budget Notes", "Reading List", "Grocery"])
        self.assertTrue(got["back"][0]["body"].startswith("# Project Plan"))
        self.assertEqual(got["garbage"], [], "unparseable text imports nothing")
        self.assertEqual(got["wrong_shape"], [], "JSON without a notes array imports nothing")

    def test_feature_persist(self):
        got = self.feature("persist")
        self.assertIsNone(got["before"], "load() returns null when nothing was saved")
        self.assertGreaterEqual(got["stored"], 1, "save() must write to localStorage")
        self.assertTrue(got["raw_is_json"], "the saved value must be JSON")
        after = got["after"]
        self.assertEqual([n["id"] for n in after["notes"]], ["n1", "n2", "n3", "n4"])
        self.assertEqual(after["notes"][2]["pinned"], True)
        self.assertEqual(after["notes"][1]["body"], "Numbers for the plan, see [[Project Plan]] and [[Missing Page]]. #finance")


if __name__ == "__main__":
    unittest.main()
